Step 4 — Read and Extract AGBD from HDF5
GEDI L4A files are HDF5 with 8 beam groups. This function loops all beams and clips to the bounding box:

extract_gedi_l4a &lt;- function(h5_path, region) {
  h5    &lt;- H5File$new(h5_path, mode = "r")
  beams &lt;- c("BEAM0000","BEAM0001","BEAM0010","BEAM0011",
             "BEAM0101","BEAM0110","BEAM1000","BEAM1011")

  results &lt;- lapply(beams, function(beam) {
    if (!beam %in% names(h5)) return(NULL)
    tryCatch({
      b &lt;- h5[[beam]]
      data.frame(
        lon        = b[["lon_lowestmode"]][],
        lat        = b[["lat_lowestmode"]][],
        agbd       = b[["agbd"]][],
        agbd_lower = b[["agbd_pi_lower"]][],
        agbd_upper = b[["agbd_pi_upper"]][],
        quality    = b[["l4_quality_flag"]][],
        degrade    = b[["degrade_flag"]][],
        beam       = beam
      )
    }, error = function(e) NULL)
  })
  h5$close_all()

  bind_rows(results) |&gt;
    filter(lon &gt;= region$lon_min, lon &lt;= region$lon_max,
           lat &gt;= region$lat_min, lat &lt;= region$lat_max)
}

scbi_raw &lt;- list.files("data/gedi_scbi", "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l4a, region = scbi) |&gt; bind_rows()

nyc_raw  &lt;- list.files("data/gedi_nyc",  "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l4a, region = nyc)  |&gt; bind_rows()

Step 4 — Read and Extract RH Metrics from HDF5
GEDI L2A stores RH metrics as a 101-element array (rh[0]…rh[100]) per shot. Index 95 = RH95, index 50 = RH50, etc.

extract_gedi_l2a &lt;- function(h5_path, region) {
  h5    &lt;- H5File$new(h5_path, mode = "r")
  beams &lt;- c("BEAM0000","BEAM0001","BEAM0010","BEAM0011",
             "BEAM0101","BEAM0110","BEAM1000","BEAM1011")

  results &lt;- lapply(beams, function(beam) {
    if (!beam %in% names(h5)) return(NULL)
    tryCatch({
      b  &lt;- h5[[beam]]
      rh &lt;- b[["rh"]][]        # matrix: shots × 101

      data.frame(
        lon          = b[["lon_lowestmode"]][],
        lat          = b[["lat_lowestmode"]][],
        elev_ground  = b[["elev_lowestmode"]][],
        rh25         = rh[, 26],   # 0-indexed: col 26 = RH25
        rh50         = rh[, 51],
        rh75         = rh[, 76],
        rh95         = rh[, 96],
        rh98         = rh[, 99],
        rh100        = rh[, 101],
        quality_flag = b[["quality_flag"]][],
        degrade_flag = b[["degrade_flag"]][],
        beam         = beam
      )
    }, error = function(e) NULL)
  })

  h5$close_all()

  bind_rows(results) |&gt;
    filter(lon &gt;= region$lon_min, lon &lt;= region$lon_max,
           lat &gt;= region$lat_min, lat &lt;= region$lat_max)
}

scbi_raw &lt;- list.files("data/gedi_l2a_scbi", "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l2a, region = scbi) |&gt; bind_rows()

nyc_raw  &lt;- list.files("data/gedi_l2a_nyc",  "\\.h5$", full.names = TRUE) |&gt;
  lapply(extract_gedi_l2a, region = nyc)  |&gt; bind_rows()

Step 7 — Compare RH Metrics Across Sites

combined &lt;- bind_rows(
  mutate(scbi_clean, region = "NEON SCBI"),
  mutate(nyc_clean,  region = "NYC Urban")
)

# Long format for multi-metric comparison
rh_long &lt;- combined |&gt;
  select(region, rh25, rh50, rh75, rh95, rh98) |&gt;
  pivot_longer(cols = c(rh25, rh50, rh75, rh95, rh98),
               names_to = "metric", values_to = "height") |&gt;
  mutate(metric = toupper(metric))

# Summary table
rh_long |&gt;
  group_by(region, metric) |&gt;
  summarise(mean = round(mean(height), 1),
            sd   = round(sd(height),   1), .groups = "drop") |&gt;
  pivot_wider(names_from = metric,
              values_from = c(mean, sd))
